from pydantic import BaseModel, Field, root_validator

class TransferInput(BaseModel):
    amount: float = Field(description='Transfer amount')
    currency: str = Field(description='Currency code')

    @root_validator
    def check_positive(cls, values):
        if values.get('amount', 0) <= 0:
            raise ValueError('Amount must be positive')
        return values

def transfer(amount: float, currency: str) -> str:
    return f'Transferred {amount} {currency}'

tool = StructuredTool.from_function(
    name='Transfer',
    description='Transfers money',
    func=transfer,
    args_schema=TransferInput,
    handle_tool_error='Transfer failed'
)
result = tool.invoke({'amount': -100, 'currency': 'USD'})
print(result)

