from langchain.agents import Tool

class ValidatedTool(Tool):
    def _validate_input(self, tool_input: str) -> bool:
        return len(tool_input) > 0

    def _run(self, tool_input: str) -> str:
        if not self._validate_input(tool_input):
            return 'Invalid input'
        return tool_input.upper()

tool = ValidatedTool(name='Validator', description='Validates input')
print(tool.invoke(''))
print(tool.invoke('hello'))

