from datetime import datetime

class EventInput(BaseModel):
    date: str = Field(description='Date in YYYY-MM-DD format')

    @validator('date')
    def validate_date(cls, v):
        datetime.strptime(v, '%Y-%m-%d')
        return v

def schedule(date: str) -> str:
    return f'Scheduled for {date}'

tool = StructuredTool.from_function(
    name='Scheduler',
    description='Schedules an event',
    func=schedule,
    args_schema=EventInput
)
result = tool.invoke({'date': '2024-13-01'})
print('Error' if 'Error' in str(result) else result)

from langchain.agents import Tool

class AuditedTool(Tool):
    audit_log: list = []

    def _run(self, tool_input: str) -> str:
        self.audit_log.append({'input': tool_input, 'timestamp': 'now'})
        return super()._run(tool_input)

tool = AuditedTool(
    name='Audited',
    description='An audited tool',
    func=lambda x: x.upper()
)
tool.invoke('first')
tool.invoke('second')
print(len(tool.audit_log))

